(()=>{const BASE='https://ready-resilience-store-31vtc5gtk-matthewxlilley-9951.vercel.app/ready-navigation-v4.js';const M={"quick-start":["A4 PDF","9 pages","10-minute setup → next horizon","Included in READY/11 + READY/12",["You want a useful first plan without completing the full library","Several people need the same basic household information","You need a paper fallback before working through Power, Water, Family or Home Systems"]],"power":["A4 PDF","16 pages","0–72 hours + 7–30 days","Included in READY/11 + READY/12",["Heating, cooking, internet or other important household functions depend on mains power","You are considering backup power and need to identify loads before choosing equipment","You want a written outage plan another household member can follow"]],"water":["A4 PDF","11 pages","3 days → 30–90 days","Included in READY/11 + READY/12",["You do not know how much water your household actually needs","Stored water exists but there is no rotation or allocation plan","You want to separate the first three days from longer replenishment planning"]],"weather-winter":["A4 PDF","10 pages","Pre-warning → recovery + seasonal review","Included in READY/11 + READY/12",["Weather warnings create last-minute decisions across home, travel, work or school","Winter disruption exposes heating, power or transport dependencies","You want a repeatable seasonal check rather than a one-off emergency checklist"]],"family":["A4 PDF","10 pages","3 / 7 / 14 / 30+ days","Included in READY/11 + READY/12",["Several people need to coordinate during a disruption","Children, dependants or split work/school routines make reunion planning important","Important care information currently lives only on phones or in one person’s head"]],"pets":["A4 PDF","9 pages","Immediate care → longer-horizon continuity","Included in READY/11 + READY/12",["A pet has medication, specialist food or a routine another person may need to follow","You need a backup carer or transport plan","Pet supplies materially affect household food or water reserves"]],"food-water":["A4 PDF","14 pages","3 / 7 / 14 / 30 / 60–90 days","Included in READY/11 + READY/12",["You have supplies but do not know how many usable days they represent","Cooking or refrigeration depends on electricity","You want a rotating pantry system rather than static emergency stock"]],"offline":["A4 PDF","11 pages","Immediate → 3–14 days → 30+ days","Included in READY/11 + READY/12",["Important contacts and instructions exist only on a phone","You want a plan for internet, mobile-network or card-payment outages","Different household members may need to act without reaching each other"]],"home-systems":["A4 PDF","12 pages","Immediate systems → 30–365-day resilience","Included in READY/11 + READY/12",["You have recently moved home or do not know where key controls are","Heating, water, internet or other services depend on multiple hidden systems","You want a maintenance/resilience plan rather than only an emergency checklist"]],"business":["A4 PDF","14 pages","3 / 7–14 / 30 / 60–90 days","Included in READY/12 only",["A small business needs a usable continuity plan without a large corporate framework","One person, supplier, system or premises location represents a major dependency","You need a paper/manual fallback when normal digital systems fail"]],"household-library":["ZIP archive","10 PDFs","3 days → 90 days + long-term home resilience","Household system: READY/01–09 + READY/11 master",["You want the household topics to work as one system rather than separate PDFs","You want one place to track dependencies, weakest links and actions across the household","You do not need the small-business continuity plan"]],"complete-library":["ZIP archive","12 PDFs","3 days → 12 months","Complete household + business system",["Household and income/business continuity affect each other","You want one complete READY/ package rather than choosing individual plans","You want master registers for cross-dependencies, financial/income continuity, recovery actions and annual review"]]};const P12=["READY/01 Quick Start — 9 pages","READY/02 Power / 72 Hours — 16 pages","READY/03 Water / 72 Hours — 11 pages","READY/04 Weather / Winter — 10 pages","READY/05 Family / 72 Hours — 10 pages","READY/06 Pets / 72 Hours — 9 pages","READY/07 Food + Water — 14 pages","READY/08 Offline — 11 pages","READY/09 Home Systems — 12 pages","READY/10 Business / 72 Hours — 14 pages","READY/11 Household Library master — 18 pages","READY/12 Complete Library master — 18 pages","README, source manifest, changelog and SHA-256 file manifest"];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function base(){if(document.querySelector('script[data-ready-v4]'))return;const s=document.createElement('script');s.src=BASE;s.defer=true;s.dataset.readyV4='1';document.head.appendChild(s)}function css(){if(document.getElementById('ready-spec-v5'))return;const s=document.createElement('style');s.id='ready-spec-v5';s.textContent='.ready-product-spec{border-top:1px solid #cfc9bd;margin-top:34px;padding-top:28px}.r-k{font:800 10px Inter,Arial,sans-serif;letter-spacing:.14em;color:#d62d20;margin-bottom:8px}.r-intro{font-size:16px;line-height:1.65;color:#333;max-width:760px}.r-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border:1px solid #cfc9bd;margin:22px 0 28px}.r-cell{padding:14px 16px;border-right:1px solid #cfc9bd;border-bottom:1px solid #cfc9bd}.r-cell:nth-child(2n){border-right:0}.r-cell:nth-last-child(-n+2){border-bottom:0}.r-label{font:800 9px Inter,Arial,sans-serif;letter-spacing:.11em;color:#67635c;margin-bottom:5px}.r-val{font:650 14px/1.35 Inter,Arial,sans-serif;color:#111}.r-cols{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(240px,.85fr);gap:24px}.r-panel{border:1px solid #cfc9bd;background:#fff;padding:20px}.r-panel h3{margin:0 0 12px;font-size:18px}.r-list{list-style:none;margin:0;padding:0;border-top:1px solid #ddd7cc}.r-list li{padding:10px 0;border-bottom:1px solid #ddd7cc;font-size:14px;line-height:1.5}.r-use{margin:0;padding-left:18px}.r-use li{margin:0 0 9px;font-size:14px;line-height:1.5}.r-combine{margin-top:24px;background:#f2efe8;border-left:5px solid var(--accent,#d62d20);padding:18px 20px}.r-combine p{margin:0;font-size:14px;line-height:1.6;color:#333}@media(max-width:760px){.r-cols,.r-grid{grid-template-columns:1fr}.r-cell{border-right:0!important;border-bottom:1px solid #cfc9bd!important}.r-cell:last-child{border-bottom:0!important}}';document.head.appendChild(s)}function refine(){const m=location.pathname.match(/\/topics\/([^/?]+)\.html$/);if(!m||!M[m[1]])return false;const slug=m[1],a=M[slug],col=document.querySelector('main .content > div'),buy=document.querySelector('.buybox'),oldT=document.querySelector('.ready-technical-product'),oldC=document.querySelector('.ready-product-contents');if(!col||!oldT||!oldC)return false;css();const overview=(oldT.querySelector('p')||oldT).textContent.replace(/PRODUCT\s*\/\s*TECHNICAL SCOPE|Technical product description/gi,'').trim();let items=[...oldC.querySelectorAll('li')].map(x=>x.textContent.trim()).filter(Boolean);if(slug==='complete-library')items=P12;const comb=(oldC.querySelector('.ready-combine')||oldC).textContent.replace(/HOW IT COMBINES\s*\//i,'').trim();const sec=document.createElement('section');sec.className='ready-product-spec';sec.innerHTML=`<div class="r-k">PRODUCT / OVERVIEW</div><h2 style="margin-bottom:12px">What this product gives you</h2><p class="r-intro">${esc(overview)}</p><div class="r-grid"><div class="r-cell"><div class="r-label">FORMAT /</div><div class="r-val">${esc(a[0])}</div></div><div class="r-cell"><div class="r-label">LENGTH /</div><div class="r-val">${esc(a[1])}</div></div><div class="r-cell"><div class="r-label">PLANNING HORIZON /</div><div class="r-val">${esc(a[2])}</div></div><div class="r-cell"><div class="r-label">SYSTEM POSITION /</div><div class="r-val">${esc(a[3])}</div></div></div><div class="r-cols"><div class="r-panel"><div class="r-k">PRODUCT / CONTENTS</div><h3>What’s inside</h3><ul class="r-list">${items.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></div><div class="r-panel"><div class="r-k">BEST USED FOR /</div><h3>Use this when</h3><ul class="r-use">${a[4].map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></div></div><div class="r-combine"><div class="r-k" style="color:#111">HOW IT COMBINES /</div><p>${esc(comb)}</p></div>`;oldT.remove();oldC.replaceWith(sec);const target=[...col.querySelectorAll(':scope > .section')].find(x=>/when a printable plan helps|when a printable library helps|when a library helps/i.test(x.textContent||''));if(target){const h=target.querySelector('h2');if(h)h.textContent='Free starting point vs paid product';const p=target.querySelector('.scope p');if(p)p.textContent='The free actions on this page help you start immediately. The paid product adds the complete printable/offline structure shown above, so the information can be completed, stored and reviewed over time.'}if(buy){const ps=[...buy.querySelectorAll(':scope > p')],g=ps.find(p=>/Digital printable planning document|Digital library delivered as a ZIP archive/i.test(p.textContent||''));if(g)g.textContent=a[0]==='ZIP archive'?a[1]+' in a downloadable ZIP archive, supplied with release/source information. Instant access after checkout; no physical goods are supplied.':a[0]+' · '+a[1]+' · printable and usable offline. Instant access after checkout; no physical goods are supplied.';const t=buy.querySelector('.ready-tech');if(t)t.innerHTML='<b>AT A GLANCE /</b> '+esc(a[2])+' · '+esc(a[3])}return true}function run(){base();let n=0,t=setInterval(()=>{if(refine()||n++>60)clearInterval(t)},50)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run,{once:true});else run()})();